head.b:skin:
:root{--bg:#f7f8fc;--card:#fff;--ink:#14162b;--muted:#5b6080;--line:#e6e8f2;--a:#6d5dfc;--b:#18c8a8;--dark:#0f1226}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.7 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}
a{color:var(--a)}
img{max-width:100%;height:auto}
.wrap{max-width:760px;margin:0 auto;padding:0 18px}
.top{background:var(--dark);color:#fff}
.top .wrap{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:14px;padding-bottom:14px}
.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font-weight:800;font-size:20px}
.brand svg{width:34px;height:34px}
.nav a{color:#c9cdf5;text-decoration:none;font-size:15px;margin-left:14px}
.nav a:hover{color:#fff}
.hero{background:linear-gradient(135deg,#0f1226,#1b1f4a);color:#fff;padding:44px 0 50px}
.hero h1{margin:0 0 8px;font-size:clamp(28px,6vw,42px);line-height:1.15}
.hero p{margin:0;color:#c9cdf5;font-size:18px}
.hero .cta{display:inline-block;margin-top:18px;background:linear-gradient(90deg,var(--a),var(--b));color:#fff;text-decoration:none;padding:11px 18px;border-radius:10px;font-weight:700}
main{padding:28px 0 40px}
.card{display:block;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px;margin:0 0 16px;text-decoration:none;color:inherit;transition:border-color .15s}
.card:hover{border-color:var(--a)}
.card h2{margin:0 0 6px;font-size:21px;line-height:1.3;color:var(--ink)}
.card p{margin:0;color:var(--muted);font-size:16px}
.meta{color:var(--muted);font-size:14px;margin-bottom:6px}
.thumb{width:100%;aspect-ratio:1200/630;object-fit:cover;border-radius:10px;margin-bottom:12px;background:var(--line)}
article.post{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:24px}
article.post h1{font-size:clamp(26px,5.5vw,36px);line-height:1.2;margin:0 0 8px}
.post-body h2{font-size:24px;line-height:1.3;margin:32px 0 8px}
.post-body h3{font-size:20px;margin:24px 0 6px}
.post-body p,.post-body li{color:#23264a}
.post-body blockquote{margin:18px 0;padding:12px 16px;border-left:4px solid var(--b);background:#f0fbf8;border-radius:6px}
.post-body code{background:#eef0fa;padding:2px 6px;border-radius:5px;font-size:15px}
.post-body pre{background:#14162b;color:#e6e8f2;padding:14px;border-radius:10px;overflow:auto}
.post-body table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}
.post-body td,.post-body th{border:1px solid var(--line);padding:8px 10px;text-align:left}
.tool-box{margin:24px 0;padding:18px;border-radius:12px;background:linear-gradient(135deg,#efeefe,#e8faf6);border:1px solid var(--line)}
.tool-box a{font-weight:700}
.labels a{display:inline-block;font-size:14px;background:#eef0fa;padding:3px 10px;border-radius:20px;margin:4px 6px 0 0;text-decoration:none}
.pager{display:flex;justify-content:space-between;margin-top:12px}
.pager a{text-decoration:none;font-weight:700}
footer{border-top:1px solid var(--line);color:var(--muted);font-size:14px;padding:22px 0 34px}
footer a{color:var(--muted)}
.hidden{display:none}
